define('taoQtiItem/qtiCreator/widgets/interactions/inlineChoiceInteraction/Widget',['lodash', 'services/features', 'taoQtiItem/qtiItem/core/Element', 'taoQtiItem/qtiCreator/widgets/interactions/inlineInteraction/Widget', 'taoQtiItem/qtiCreator/widgets/choices/inlineChoice/Widget', 'taoQtiItem/qtiCreator/widgets/interactions/inlineChoiceInteraction/states/states', 'tpl!taoQtiItem/qtiCreator/tpl/inlineInteraction/inlineChoiceInteraction', 'tpl!taoQtiItem/qtiCreator/tpl/inlineInteraction/inlineChoice'], function (_, features, Element, InteractionWidget, ChoiceWidget, states, inlineChoiceInteractionTpl, inlineChoiceTpl) {
  var InlineChoiceInteractionWidget = InteractionWidget.clone();
  InlineChoiceInteractionWidget.initCreator = function (options) {
    this.registerStates(states);
    InteractionWidget.initCreator.call(this);
    this.$choiceOptionForm = options.choiceOptionForm;
    _.forEach(this.element.getChoices(), choice => {
      this.buildChoice(choice);
    });
    this.$container.find('.tlb-title').remove();
  };
  InlineChoiceInteractionWidget.renderChoice = function (choice, shuffleChoice) {
    var interaction = this.element;
    var interactionData = {
      interaction
    };
    var container = choice.getBody();
    var body = container.render(_.clone(interactionData, true), null, container.qtiClass + '.' + interaction.qtiClass, interaction.getRenderer());
    var dir = choice.getRootElement().getBody().attributes.dir;
    var shuffleIsVisible = features.isVisible('taoQtiItem/creator/interaction/inlineChoice/property/shuffle');
    var tplData = {
      tag: choice.qtiClass,
      serial: choice.serial,
      attributes: choice.attributes,
      body,
      interactionShuffle: shuffleIsVisible && shuffleChoice,
      dir: dir
    };
    return inlineChoiceTpl(tplData);
  };
  InlineChoiceInteractionWidget.renderInteraction = function () {
    var interaction = this.element;
    var shuffleChoice = interaction.attr('shuffle');
    var dir = this.element.getRootElement().getBody().getAttributes().dir;
    var tplData = {
      tag: interaction.qtiClass,
      serial: interaction.serial,
      attributes: interaction.attributes,
      choices: [],
      dir: dir
    };
    _.forEach(interaction.getChoices(), choice => {
      if (Element.isA(choice, 'choice')) {
        tplData.choices.push(this.renderChoice(choice, shuffleChoice));
      }
    });
    return inlineChoiceInteractionTpl(tplData);
  };
  InlineChoiceInteractionWidget.buildChoice = function (choice, options) {
    ChoiceWidget.build(choice, this.$container.find('.widget-inlineChoice[data-serial="' + choice.serial + '"]'), this.$choiceOptionForm, options);
  };
  InlineChoiceInteractionWidget.buildContainer = function () {
    var previous, next;
    if (this.$original.length) {
      previous = this.$original[0].previousSibling;
      next = this.$original[0].nextSibling;
      if (!previous || previous.nodeType === 3 && previous.nodeValue === '' || previous.nodeType !== 3) {
        this.$original.before('&nbsp;');
      }
      if (!next || next.nodeType === 3 && next.nodeValue === '' || next.nodeType !== 3) {
        this.$original.after('&nbsp;');
      }
    }
    this.$itemContainer = this.$original.parents('.item-editor-item');
    this.$itemContainer.append(this.renderInteraction());
    this.$container = this.$itemContainer.find('.widget-inlineChoiceInteraction[data-serial=' + this.element.getSerial() + ']');
  };
  return InlineChoiceInteractionWidget;
});
