define('taoQtiItem/qtiCreator/helper/elementSupport',[], function () {
  'use strict';
  var isFigureSupportedInParent = $container => {
    var notSupported = $container.closest('.qti-choice, .qti-flow-container').length || $container.closest('.qti-table caption').length || $container.closest('.qti-modalFeedback').length || $container.closest('.qti-customInteraction').length && !$container.closest('[data-element-support-figure="true"]').length;
    return !notSupported;
  };
  return {
    isFigureSupportedInParent
  };
});
